def transform(grid):
    h, w = len(grid), len(grid[0])
    barrier = next(
        (r for r, row in enumerate(grid) if row and all(v == 2 for v in row)),
        None
    )
    if barrier is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    particles = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == 4]

    for r, c in particles:
        out[r][c] = 0

        if r < barrier:
            # The particle falls one cell toward the barrier.
            if r + 1 < barrier:
                out[r + 1][c] = 4
            else:
                out[r][c] = 4

            # On reaching the cell two rows above the barrier, it leaves
            # diagonal trails spreading upward from its new position.
            if r == barrier - 2:
                center_r = r + 1
                out[center_r][c] = 4
                for k in range(1, center_r + 1):
                    rr = center_r - k
                    for cc in (c - k, c + k):
                        if 0 <= cc < w:
                            out[rr][cc] = 4
        elif r > barrier:
            # Below the barrier, particles fall downward one cell.
            out[min(r + 1, h - 1)][c] = 4

    return out
